   font-family: 'Montserrat', cursive;
   font-size: 25.5px; /* was 2em */
   }
   .above-content {
   position: absolute;
   top: 0;
   left: 0;
   width: 100%;
   z-index: 1; /* Umožňuje zobrazit tento obsah nad content-wrapper */
   }
   /* Skrytí tabulky pro mobilní zařízení */
   .desktop-only {
   display: table; /* Výchozí zobrazení */
   }
   .mobile-only {
   display: none; /* Skrytí na desktopu */
   }
   /* Media query pro mobilní zařízení */
   @media (max-width: 767px) {
   .desktop-only {
   display: none; /* Skrytí na mobilních zařízeních */
   }
   .mobile-only {
   display: table; /* Zobrazení na mobilních zařízeních */
   }
   }
   /* Styl pro obrázky v buňkách */
   td img {
   display: block; /* Odstranění mezery pod obrázkem */
   width: 100%;
   height: auto; /* Zachování poměru stran obrázku */
   margin: 0; /* Odstranění vnějších mezer */
   padding: 0; /* Odstranění vnitřních mezer */
   border: none; /* Odstranění případných okrajů obrázku */
   }
   /* Styl pro buňky s nulovými okraji a vycpávkami */
   td {
   padding: 0;
   margin: 0;
   border: 0;
   text-align: center;
   vertical-align: middle;
   width: auto; /* Automatická šířka podle obsahu */
   background-color: rgb(189, 187, 187); /* Zajistí, že pozadí buňky bude odpovídat barvě */
   }
   /* Styl pro tabulku */
   table {
   border-collapse: collapse; /* Sloučení okrajů tabulky */
   width: 100%;
   }
   /* Pro mobilní zařízení */
   @media only screen and (max-width: 768px) {
   #responsive-image {
   height: auto;
   max-height: 350px; /* Výška obrázku nebude větší než 350px */
   width: 100%; /* Obrázek se přizpůsobí šířce obrazovky */
   }
   }
