   }
   .grid-container:{
   width: 100%;
   }
   .grid-box{
   width: fit-content;
   height: fit-content;
   display: grid;
   gap: 3px;
   }      
   .grid-item{
   grid-column: span 1;
   grid-row: span 1;
   min-height: 465px;
   outline: 3px solid black;
   }
   .grid-item > img{
   margin: 0;
   padding: 0;
   width: 100%;
   height: auto;
   }
   .grid-item > p.header {
   font-size: 20px;
   background-color: rgb(0, 0, 0);
   color: white;
   font-weight: bold;
   display: flex;
   justify-content: center;
   align-items: center;
   flex-wrap: nowrap;
   height: 4em;
   margin: 0;
   padding: 0.1em;
   line-height: 24px;
   vertical-align: middle;
   text-align: center;
   }
   .grid-item > p.text {
   display: flex;
   justify-content: center;
   align-items: center;
   flex-wrap: nowrap;
   vertical-align: middle;
   text-align: center;
   padding: 0 0.3em;
